specimens.css:
/* 静态快照：Modal 的 .root 在真实产品里是 body 上的 fixed 全屏遮罩层，这里改回文档流，
   同时保留它作为 .mask 绝对定位的父级。 */
.root.snapshotStatic { position: relative; }

/* 静态快照：Modal 的 .root 在真实产品里是 body 上的 fixed 全屏遮罩层，这里改回文档流，
   同时保留它作为 .mask 绝对定位的父级。 */
.root.snapshotStatic { position: relative; }

/* 静态快照：Modal 的 .root 在真实产品里是 body 上的 fixed 全屏遮罩层，这里改回文档流，
   同时保留它作为 .mask 绝对定位的父级。 */
.root.snapshotStatic { position: relative; }

/* 静态快照：面板真实渲染在 body 的 portal 里，带 position:fixed 与内联坐标；这里拉回文档流，
   relative 同时保住 ::before 菜单皮肤的包含块。悬停态无法静态触发，把 .member:hover 的两条规则
   原样搬到 .memberForceHover 上。 */
.panel.panelSnapshot { position: relative; inset: auto; }
.member.memberForceHover { --dsw-elevation-stroke-color: var(--dsw-alias-border-l3); box-shadow: var(--dsw-elevation-panel); }
.member.memberForceHover .memberModel { display: inline; }
